  ('faithfulness', '/ˈfeɪθ.fəl.nəs/', '忠诚；可靠性', 'Quality of being loyal and reliable in relationships.'),
  ('renunciation', '/rɪˌnʌn.siˈeɪ.ʃən/', '放弃；声明退出', 'The act of rejecting or giving up something voluntarily.'),
