  ('cogent', 1, 'cogent argument', 'Researchers provided a cogent argument to support their findings during the presentation.', '研究人员在演示中提供了有说服力的论点来支持他们的发现。', 'academic'),
  ('cogent', 2, 'cogent evidence', 'The scientist presented cogent evidence to validate the new theory in her paper.', '这位科学家在她的论文中提出了有说服力的证据来验证这一新理论。', 'science_tech'),
  ('cogent', 3, 'cogent reasoning', 'His cogent reasoning impressed the committee members during the evaluation process.', '他的有说服力的推理在评估过程中给委员会成员留下了深刻印象。', 'work'),
  ('circuitous', 1, 'circuitous routes', 'Travelers often find circuitous routes to avoid heavy traffic during peak hours.', '旅行者通常发现迂回的路线以避开高峰时段的交通拥堵。', 'travel'),
  ('circuitous', 2, 'circuitous reasoning', 'Researchers criticized the study for its circuitous reasoning that obscured the main argument.', '研究人员批评该研究的迂回推理使主要论点变得模糊。', 'academic'),
  ('circuitous', 3, 'circuitous discussions', 'In meetings, circuitous discussions can lead to confusion and delay decision-making.', '在会议上，迂回的讨论可能导致混乱并延迟决策。', 'work')
  ) AS v(headword, sort_order, collocation, sentence, translation_zh, scene)
  JOIN vocab_words w ON lower(w.headword) = v.headword
ON CONFLICT (word_id, sort_order) DO UPDATE
  SET collocation = EXCLUDED.collocation,
      sentence = EXCLUDED.sentence,
      translation_zh = EXCLUDED.translation_zh,
      scene = EXCLUDED.scene;

SELECT 'p4/5 AFTER' AS stage,
       (SELECT count(*) FROM vocab_words WHERE def_zh IS NOT NULL) AS words_with_def,
       (SELECT count(*) FROM vocab_examples) AS examples;

-- 中间片不做判定。趋势看上面两行:words_with_def 和 examples 都应递增。

COMMIT;
